function validate([nums, target]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (!nums.every(v => Number.isInteger(v) && v >= 1 && v <= 1000)) return 'Each value is an integer from 1 to 1000.';
  if (!Number.isInteger(target) || target < 1 || target > 1000) return 'target is between 1 and 1000.';
  return null;
}

