function lengthOfLongestSubsequence(nums, target) {
  const dp = new Array(target + 1).fill(-1);
  dp[0] = 0;
  for (const num of nums) {
    for (let sum = target; sum >= num; sum--) {
      if (dp[sum - num] !== -1) {
        dp[sum] = Math.max(dp[sum], dp[sum - num] + 1);
      }
    }
  }
  return dp[target];
}

