function lengthOfLongestSubsequence(nums, target) {
  // Try every subset of positions.
  let best = -1;
  for (let mask = 1; mask < 1 << nums.length; mask++) {
    let sum = 0, count = 0;
    for (let i = 0; i < nums.length; i++) if (mask & (1 << i)) { sum += nums[i]; count++; }
    if (sum === target && count > best) best = count;
  }
  return best;
}

