function generate(rand, size) {
  if (size === 'large') {
    const n = 1000;
    const style = Math.floor(rand() * 3);
    if (style === 0) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000)), 1 + Math.floor(rand() * 1000)];
    if (style === 1) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 10)), 1000 - Math.floor(rand() * 50)];
    // Only even values and an odd target: no subsequence can match.
    return [Array.from({ length: n }, () => 2 + 2 * Math.floor(rand() * 500)), 1 + 2 * Math.floor(rand() * 500)];
  }
  const n = 1 + Math.floor(rand() * 10);
  const top = rand() < 0.6 ? 5 : 20;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const target = 1 + Math.floor(rand() * Math.min(1000, top * 3));
  return [nums, target];
}
